import{_ as p,o as e,c as s,y as a}from"./chunks/framework.CNTkXYA8.js";const d=JSON.parse('{"title":"【Ubuntu】小技巧","description":"","frontmatter":{"title":"【Ubuntu】小技巧","date":"2018-11-18T11:22:00.000Z"},"headers":[],"relativePath":"blog/ubuntu.md","filePath":"source/old_posts/ubuntu.md"}'),n={name:"blog/ubuntu.md"};function o(u,t,r,_,i,l){return e(),s("div",null,[...t[0]||(t[0]=[a("<p>1.在 usr/share/applications/ 中可以找到 .desktop 文件，修改其内容可以修改你的桌面快捷方式，</p><p>例如图标或者分类还可以新建你的 .desktop ，如果你安装的软件没有自动建造快捷方式的话，你</p><p>可以帮帮它，比如帮它设置一个图标。然后为它指定一个执行的路径。</p><p>（例如我下载的Listen1，需要自己配置快捷方式。）</p><p>2.类似于Windows的环境变量Path，在Linux下可以通过在 /usr/bin/ 下新建文件，可以在终端达到</p><p>同样的效果。</p><p>3.安装一下主题。那样会让你的Linux更好看。</p><p>-----18/11/?-----</p><p>4.遇到类似 E: 无法获得锁 /var/lib/apt/lists/lock - open (11: 资源暂时不可用) 的情况</p><p>大概率是开机的时候系统自己后台调用了apt，所以过一会就好了（仅代表部分情况）</p><p>-----18/12/2-----</p>",11)])])}const b=p(n,[["render",o]]);export{d as __pageData,b as default};
